entries[20854] = { ["name"] = "Vorlage: Amulett des Mondes", ["text"] = "Benötigt Juwelenschleifen (110)\nBenutzen: Lehrt Euch die Herstellung eines Amuletts des Mondes.\nVerkaufspreis:\nAmulett des Mondes\nWird beim Anlegen gebunden\nHals\n+4 Intelligenz\n+4 Willenskraft\nBenötigt Stufe 25\nBenutzen: Gewährt nahen Gruppenmitgliedern 30 Min. lang 10 zusätzliche Willenskraft.\n10 Aufladungen\nVerkaufspreis:\nBenötigt Geringer Mondstein (2), Bronzefassung" }
